  `price` DECIMAL(10,2) NULL,
  `paid_at` DATETIME NULL,
  `source` VARCHAR(64) NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_guests_hash` (`hash`),
  KEY `idx_guest_event_status` (`event_id`, `status`),
  KEY `idx_guest_calendar` (`calendar_id`, `status`),
  KEY `idx_guest_order` (`registration_no`),
  KEY `idx_guest_email` (`email`),
  CONSTRAINT `fk_guests_event_id` FOREIGN KEY (`event_id`) REFERENCES `wp_fe_event_details` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_guests_calendar_id` FOREIGN KEY (`calendar_id`) REFERENCES `wp_fe_calendars` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_guests_ticket_type_id` FOREIGN KEY (`ticket_type_id`) REFERENCES `wp_fe_ticket_types` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

